<script setup lang="ts">import { computed } from 'vue';import { dictionary, dictionaryState } from '@/utils/dictionaries';const props = defineProps<{ code: string }>(), model = defineModel<string>();const values = computed(() => dictionary(props.code)), error = computed(() => dictionaryState.errors[props.code]);const placeholder = computed(() => error.value || '请选择')</script><template><el-select v-model="model" :placeholder="placeholder"><el-option v-for="v in values" :key="v.value" :label="v.label" :value="v.value" /></el-select></template>
